from pathlib import Path
p=Path('components/game-runtime-pro-v4.tsx')
s=p.read_text()
old="    startAuto(type:'actor'|'object',id:string,go:any){if(!this.canClick(type,id))return;const d=Math.hypot(go.x-this.player.x,go.y-this.player.y);const speed=Math.max(320,Math.min(650,d/1.8));this.autoTarget={type,id,go,speed,jqDistanceAwareWalk:true};this.autoOpenLock=false;setCloud(`Indo até ${type==='actor'?'o personagem':'a evidência'}…`)}"
new="    startAuto(type:'actor'|'object',id:string,go:any){if(!this.canClick(type,id))return;const d=Math.hypot(go.x-this.player.x,go.y-this.player.y);const speed=Math.max(320,Math.min(650,d/1.8)),token=`${type}:${id}:${Date.now()}`;this.autoTarget={type,id,go,speed,jqDistanceAwareWalk:true,token};this.autoOpenLock=false;setCloud(`Indo até ${type==='actor'?'o personagem':'a evidência'}…`);window.setTimeout(()=>{const t=this.autoTarget;if(!t||t.token!==token||blockedRef.current||!this.player)return;const dx=t.go.x-this.player.x,dy=t.go.y-this.player.y,dist=Math.max(1,Math.hypot(dx,dy)),radius=Math.max(72,Number(runtimeSettings?.settings?.interaction_radius||120)*.72);this.player.setPosition(t.go.x-dx/dist*radius,t.go.y-dy/dist*radius);this.player.body?.setVelocity(0,0);this.player.angle=0;this.autoTarget=null;const next:Near={type:t.type,id:t.id};this.lastNear=`${t.type}:${t.id}`;nr.current=next;setNear(next);setDistance(null);setCloud('Alvo alcançado • abrindo interação…');const pulse=this.add.circle(t.go.x,t.go.y,24,0xe7c15c,.08).setStrokeStyle(3,0xe7c15c,.92).setDepth(1750);this.tweens.add({targets:pulse,scale:2.15,alpha:0,duration:420,ease:'Cubic.easeOut',onComplete:()=>pulse.destroy()});this.autoOpenLock=true;window.setTimeout(()=>{if(!blockedRef.current)primaryRef.current();this.autoOpenLock=false},120)},3600)}"
if old not in s: raise RuntimeError('startAuto anchor missing')
p.write_text(s.replace(old,new,1))
